using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using NUnit.Framework;
using UnityEngine.TestTools;
using UnityEngine.SceneManagement;
namespace Wildfolk.Tests
{
    public sealed class StorePlayTests
    {
        private string root,previous;private AccountService account;private Cloud cloud;private StoreService service;private DevelopmentStoreBilling billing;private DevelopmentStoreTransport transport;
        private sealed class Identity:IAccountIdentityProvider{public string PlayerId=>"store-isolated-player";public bool Linked=>true;public Task Connect()=>Task.CompletedTask;public Task UseExisting()=>Task.CompletedTask;public void SignOut(bool clearSession=false){}}
        private sealed class Cloud:IAccountCloudTransport,IEconomyTransport
        {
            Task<AccountReply> IAccountCloudTransport.Call(string op,Dictionary<string,object> input)=>Task.FromResult(new AccountReply{ok=true,profile=new CloudAccountProfile{Schema=1,PlayerId="store-isolated-player",SupportId="LF-1234-5678-90AB-CDEF-1234",CreatedAt="2026-10-28T00:00:00Z",ProviderLinked=true,ClassProfile=CloudClassProfile.From(AccountProgression.New()),Entitlements=Array.Empty<AccountEntitlement>()}});
            Task<EconomyReply> IEconomyTransport.Call(string op,Dictionary<string,object> input)=>Task.FromResult(new EconomyReply{ok=true});
        }
        [UnitySetUp]public IEnumerator Setup(){previous=UnityEditor.SessionState.GetString("Wildfolk.QA.Directory","");root=Path.Combine(Path.GetTempPath(),"LowfireStorePlay-"+Guid.NewGuid().ToString("N"));UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",root);ClassProfiles.DevelopmentProviders(new LocalAccountProgressionStore(Path.Combine(root,"guest")));cloud=new Cloud();account=AccountService.InstallDevelopment(new Identity(),cloud);EconomyService.InstallDevelopment(account,cloud);SceneFlow.Repository=SaveRepository.Default();yield return SceneManager.LoadSceneAsync(SceneFlow.HomeScene);yield return null;yield return Await(account.Connect());billing=new DevelopmentStoreBilling();transport=new DevelopmentStoreTransport(account.Profile.PlayerId,BackendSettings.Current.Environment.Id);service=StoreService.InstallDevelopment(account,transport,billing);yield return Await(service.Open());Assert.That(service.CanBuy,Is.True);}
        [TearDown]public void Cleanup(){service.Dispose();EconomyService.ClearDevelopment();ClassProfiles.AttachCloud(null);SceneFlow.Repository=null;UnityEditor.SessionState.SetString("Wildfolk.QA.Directory",previous);if(Directory.Exists(root))Directory.Delete(root,true);}
        private static IEnumerator Await(Task task){while(!task.IsCompleted)yield return null;if(task.IsFaulted)throw task.Exception;}
        [UnityTest]public IEnumerator CancelNoFillAndFailureAreNonGrantsAndReleaseGate(){foreach(var result in new[]{BillingOutcome.Cancelled,BillingOutcome.Unavailable,BillingOutcome.Failed}){billing.Next=result;yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(transport.Grants,Is.Zero);Assert.That(service.Busy,Is.False);}Assert.That(billing.Buys,Is.EqualTo(3));}
        [UnityTest]public IEnumerator PendingPaymentIsDurableButNeverARewardUntilServerVerifies(){billing.Next=BillingOutcome.Pending;transport.Pending=true;yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(service.Phase,Is.EqualTo(StorePhase.Pending));Assert.That(service.CanBuy,Is.False);Assert.That(transport.Grants,Is.Zero);var scope=BackendSettings.Current.Environment.Id+":"+account.Profile.PlayerId;Assert.That(PurchaseJournal.Open(scope).State.Pending.Count,Is.EqualTo(1));transport.Pending=false;yield return Await(service.Recover());Assert.That(transport.Grants,Is.EqualTo(1));yield return Await(service.Recover());Assert.That(transport.Grants,Is.EqualTo(1));}
        [UnityTest]public IEnumerator ServerUnavailableBeforeStartCannotOpenGoogleUI(){transport.FailStart=true;yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(billing.Buys,Is.Zero);Assert.That(transport.Grants,Is.Zero);Assert.That(service.Busy,Is.False);}
        [UnityTest]public IEnumerator PurchaseProofSurvivesServerFailureAndServiceRestart(){transport.FailVerification=true;yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(transport.Grants,Is.Zero);service.Dispose();billing=new DevelopmentStoreBilling();transport.FailVerification=false;service=StoreService.InstallDevelopment(account,transport,billing);yield return Await(service.Open());Assert.That(transport.Grants,Is.EqualTo(1));Assert.That(service.Phase,Is.EqualTo(StorePhase.Completed));}
        [UnityTest]public IEnumerator ParallelTapAndAccountChangeNeverGrantToNewAccount(){billing.Held=new TaskCompletionSource<BillingResult>();var purchase=service.Purchase("lowfire_gems_24");yield return null;yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(billing.Buys,Is.EqualTo(1));var binding=service.State.AccountBinding;account.SignOut();billing.Held.SetResult(new BillingResult{Outcome=BillingOutcome.Purchased,Purchase=new StorePurchase{ProductId="lowfire_gems_24",Token="fixture-late-token",AccountBinding=binding,ProfileBinding=new string('b',64)}});yield return Await(purchase);Assert.That(transport.Grants,Is.Zero);Assert.That(service.State,Is.Null);var scope=BackendSettings.Current.Environment.Id+":store-isolated-player";Assert.That(PurchaseJournal.Open(scope).State.Pending[0].Token,Is.EqualTo("fixture-late-token"));}
        [UnityTest]public IEnumerator FailedFreshMetadataClearsCachedPricesAndDisconnectDisablesPurchase(){billing.FetchFails=true;yield return Await(service.Open());Assert.That(service.Prices,Is.Empty);Assert.That(service.CanBuy,Is.False);billing.FetchFails=false;yield return Await(service.Open());billing.Emit(null);Assert.That(service.Prices,Is.Empty);Assert.That(service.CanBuy,Is.False);}
        [UnityTest]public IEnumerator DuplicateCallbacksAndRepeatedOpenDoNotRestoreConsumedCurrency(){yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(transport.Grants,Is.EqualTo(1));var p=billing.Purchases[0];billing.Emit(p);billing.Emit(p);yield return null;while(service.Busy)yield return null;yield return Await(service.Open());Assert.That(transport.Grants,Is.EqualTo(1));}
        [UnityTest]public IEnumerator DeletionClearsPreviousSessionJournalBeforeStoreIsReopened(){billing.Next=BillingOutcome.Pending;transport.Pending=true;yield return Await(service.Purchase("lowfire_gems_24"));var scope=BackendSettings.Current.Environment.Id+":"+account.Profile.PlayerId;var path=PurchaseJournal.Open(scope).Path;Assert.That(File.Exists(path),Is.True);service.Dispose();service=StoreService.InstallDevelopment(account,transport,new DevelopmentStoreBilling());yield return Await(account.PrepareDeletion(true));Assert.That(account.State,Is.EqualTo(AccountConnection.DeletionPending));Assert.That(File.Exists(path),Is.False);Assert.That(File.Exists(path+".backup"),Is.False);Assert.That(service.CanBuy,Is.False);}
        [UnityTest]public IEnumerator OfflineAndUnsupportedProductRejectBeforeBilling(){account.KeepLocal();yield return Await(service.Purchase("lowfire_gems_24"));Assert.That(billing.Buys,Is.Zero);yield return Await(service.Open());Assert.That(service.Phase,Is.EqualTo(StorePhase.AccountRequired));}
    }
}
